const activeScreen = ref('home')
const marketMode = ref('match')
const theme = ref('light')

function setTheme(value) {
  theme.value = value
  window.localStorage?.setItem('socceroctupus-orbit-theme', value)
}

onMounted(() => {
  const savedTheme = window.localStorage?.getItem('socceroctupus-orbit-theme')
  if (savedTheme === 'light' || savedTheme === 'dark') theme.value = savedTheme
  else theme.value = window.matchMedia?.('(prefers-color-scheme: dark)').matches ? 'dark' : 'light'
})
